 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # A uniform interior row/column divides two panels. Find that divider.
    divider = None
    for r, row in enumerate(grid):
        if 0 < r < h - 1 and len(set(row)) == 1:
            divider = ('row', r)
            break
    if divider is None:
        for c in range(w):
            if 0 < c < w - 1 and len({grid[r][c] for r in range(h)}) == 1:
                divider = ('col', c)
                break
    if divider is None:
        raise ValueError('No uniform interior divider')
    if divider[0] == 'row':
        k = divider[1]
        panels = (grid[:k], grid[k + 1:])
        out_h, out_w = len(panels[0]), w
    else:
        k = divider[1]
        panels = ([row[:k] for row in grid], [row[k + 1:] for row in grid])
        out_h, out_w = h, len(panels[0][0])
    colors = [{v for row in panel for v in row} for panel in panels]
    shared = sorted(colors[0] & colors[1])
    if not shared:
        raise ValueError('Panels share no colors')
    color = shared[0]
    return [[color] * out_w for _ in range(out_h)]
